ID = "math_ex_ch6_complexes_7"


def figure(a, b):
    i = (a + b) / 2
    return plan("Les points A et B", "Place I, le milieu de [AB], avant de chercher les ensembles de points.",
                [("A", a.real, a.imag, "cyan", "no"), ("B", b.real, b.imag, "orange", "se")],
                xs=(int(min(a.real, b.real)) - 2, int(max(a.real, b.real)) + 2), ys=(-3, 3),
                autres=[{"f": "ligne", "pts": [[a.real, a.imag], [b.real, b.imag]], "couleur": "faible", "trait": "pointille"}])


def ass_reel():
    G = [("1", "Z est réel"), ("2", "Z est imaginaire pur")]
    D = [("a", "Im(Z) = 0"), ("b", "Re(Z) = 0"), ("c", "|Z| = 0")]
    C = {"1": "a", "2": "b"}
    R = {
      "1-a": ("Oui : un réel n'a pas de partie imaginaire.", "برافو: le réel ما عندوش la partie imaginaire."),
      "1-b": ("Re(Z) = 0, c'est Z sur l'axe imaginaire : imaginaire pur, pas réel.", "لا، la partie réelle zéro، يعني Z على l'axe imaginaire، ماشي réel."),
      "1-c": ("|Z| = 0 veut dire Z = 0 seulement ; un réel peut être non nul.", "لا، le module zéro، يعني غير Z égale zéro. و le réel ممكن ماشي zéro."),
      "2-a": ("Im(Z) = 0, c'est Z réel, sur l'axe réel.", "لا، la partie imaginaire zéro، يعني Z réel، على l'axe réel."),
      "2-b": ("Oui : un imaginaire pur a une partie réelle nulle.", "برافو: l'imaginaire pur، la partie réelle ديالو zéro."),
      "2-c": ("|Z| = 0 veut dire Z = 0 seulement.", "لا، le module zéro، يعني غير Z égale zéro."),
    }
    return association("fa_c7_6", "Plus facile : réel ou imaginaire pur", "Relie chaque phrase à sa condition (Z = X + iY).",
      "سؤال ساهل: ربط كل جملة مع la condition ديالها.", "Relie chaque phrase à sa condition.", G, D, C, R,
      ("(1 ; a) (2 ; b) : |Z| = 0 est de trop, il ne donne que Z = 0.", "un مع a، deux مع b. le module zéro زايد: كيعطي غير Z égale zéro."))


